/// Undefined bits are refused.
impl Wire for MoveButtons {
    fn encode(&self, e: &mut Encoder<'_>) {
        e.u16(self.bits());
    }
    fn decode(d: &mut Decoder<'_>) -> Result<Self, DecodeError> {
        Self::from_bits(d.u16()?).ok_or(DecodeError::Invalid("move buttons"))
    }
}

impl FuzzSample for MoveButtons {
    #[allow(clippy::cast_possible_truncation)] // below(64) fits u16
    fn fuzz_sample(rng: &mut Rng) -> Self {
        Self::from_bits(rng.below(u32::from(Self::ALL.bits()) + 1) as u16).unwrap_or(Self::NONE)
    }
}

/// `seq u32, tick u64, buttons u16, yaw u16, aim yaw u16, aim pitch u16`
/// (20 bytes).
impl Wire for MoveInput {
    fn encode(&self, e: &mut Encoder<'_>) {
        self.seq.encode(e);
        self.tick.encode(e);
        self.buttons.encode(e);
        self.yaw.encode(e);
        self.aim.yaw.encode(e);
        self.aim.pitch.encode(e);
    }
    fn decode(d: &mut Decoder<'_>) -> Result<Self, DecodeError> {
        Ok(Self {
            seq: InputSeq::decode(d)?,
            tick: Tick::decode(d)?,
            buttons: MoveButtons::decode(d)?,
            yaw: Angle16::decode(d)?,
            aim: AimAngles {
                yaw: Angle16::decode(d)?,
                pitch: Angle16::decode(d)?,
            },
        })
    }
}

impl FuzzSample for MoveInput {
    fn fuzz_sample(rng: &mut Rng) -> Self {
        Self {
            seq: InputSeq::fuzz_sample(rng),
            tick: Tick::fuzz_sample(rng),
            buttons: MoveButtons::fuzz_sample(rng),
            yaw: Angle16::fuzz_sample(rng),
            aim: AimAngles {
                yaw: Angle16::fuzz_sample(rng),
                pitch: Angle16::fuzz_sample(rng),
            },
        }
    }
}

impl Wire for ContentHash {
    fn encode(&self, e: &mut Encoder<'_>) {
        e.bytes(self.as_bytes());
    }
    fn decode(d: &mut Decoder<'_>) -> Result<Self, DecodeError> {
        Ok(Self::from_bytes(d.array()?))
    }
}

impl FuzzSample for ContentHash {
    fn fuzz_sample(rng: &mut Rng) -> Self {
        let mut b = [0u8; 32];
        for chunk in b.chunks_mut(8) {
            for (dst, src) in chunk.iter_mut().zip(rng.next_u64().to_le_bytes()) {
                *dst = src;
            }
        }
        Self::from_bytes(b)
    }
}

